import json, sys
data = json.load(sys.stdin)
# Print structure
if isinstance(data, dict):
    for k in data.keys():
        print(f'Key: {k}')
        if isinstance(data[k], (dict, list)):
            print(f'  Type: {type(data[k]).__name__}')
            if isinstance(data[k], list) and len(data[k]) > 0:
                print(f'  Length: {len(data[k])}')
                print(f'  First item: {data[k][0]}')
        else:
            print(f'  Value: {data[k][:100] if isinstance(data[k], str) else data[k]}')
